"""Document Quality Inspector service for evaluating extraction fidelity and data health."""

import string
from dataclasses import dataclass, asdict
from typing import List, Dict, Any
from app.services.ingestion.extractor import ExtractedPage


@dataclass
class QualityInspectionResult:
    """Diagnostic report and composite score generated by Document Quality Inspector."""

    quality_score: float  # 0.0 to 1.0
    ocr_needed: bool
    total_pages: int
    blank_pages: int
    low_density_pages: int
    garbled_ratio: float
    detected_tables_count: int
    recommendations: List[str]
    details_by_page: List[Dict[str, Any]]

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


class DocumentQualityInspector:
    """Evaluates extraction success, table structure, and OCR necessity before indexing."""

    PRINTABLE_SET = set(string.printable)

    @classmethod
    def inspect(cls, pages: List[ExtractedPage]) -> QualityInspectionResult:
        total_pages = len(pages)
        if total_pages == 0:
            return QualityInspectionResult(
                quality_score=0.0,
                ocr_needed=True,
                total_pages=0,
                blank_pages=0,
                low_density_pages=0,
                garbled_ratio=1.0,
                detected_tables_count=0,
                recommendations=["Document contains 0 extractable pages."],
                details_by_page=[],
            )

        blank_pages = 0
        low_density_pages = 0
        total_chars = 0
        non_printable_chars = 0
        detected_tables = 0
        page_details = []
        recommendations = []

        for p in pages:
            raw_text = p.text.strip()
            char_count = len(raw_text)
            total_chars += char_count

            # Count non-printable or corrupt glyphs
            unprintable = sum(1 for c in raw_text if c not in cls.PRINTABLE_SET and ord(c) < 128)
            non_printable_chars += unprintable

            # Table detection heuristics: multiple pipes or tabs
            table_lines = sum(1 for line in raw_text.splitlines() if line.count("|") >= 2 or line.count("\t") >= 2)
            has_table = table_lines >= 2
            if has_table:
                detected_tables += 1

            # Check density
            is_blank = char_count == 0
            is_low_density = not is_blank and char_count < 60

            if is_blank:
                blank_pages += 1
            if is_low_density:
                low_density_pages += 1

            page_details.append({
                "page_number": p.page_number,
                "character_count": char_count,
                "has_table_structure": has_table,
                "is_blank": is_blank,
                "is_low_density": is_low_density,
            })

        # Calculate metrics
        garbled_ratio = (non_printable_chars / max(1, total_chars)) if total_chars > 0 else 0.0
        
        # Scanned PDF detection heuristic: if > 30% of pages are blank or low density
        ocr_needed = (blank_pages + low_density_pages) / max(1, total_pages) >= 0.35

        # Composite score calculation (starts at 1.0, penalizes defects)
        score = 1.0
        if ocr_needed:
            score -= 0.40
            recommendations.append("High proportion of blank or low-density pages detected. Document appears scanned; local OCR recommended.")
        if garbled_ratio > 0.05:
            score -= min(0.30, garbled_ratio * 2.0)
            recommendations.append("Elevated non-printable or corrupted character ratio detected.")
        if blank_pages > 0 and not ocr_needed:
            score -= (blank_pages / total_pages) * 0.15
            recommendations.append(f"{blank_pages} blank page(s) detected in document.")

        score = max(0.05, min(1.0, round(score, 4)))

        if score >= 0.85:
            recommendations.append("High extraction fidelity. Document text, headings, and structure successfully parsed.")

        return QualityInspectionResult(
            quality_score=score,
            ocr_needed=ocr_needed,
            total_pages=total_pages,
            blank_pages=blank_pages,
            low_density_pages=low_density_pages,
            garbled_ratio=round(garbled_ratio, 4),
            detected_tables_count=detected_tables,
            recommendations=recommendations,
            details_by_page=page_details,
        )

